from django.db import migrations, models


NIVEAUX = [("Classe préparatoire", 1), ("BTS", 2), ("Licence", 3), ("Master", 4), ("Formation continue", 5)]


def convertir_indicateurs(apps, schema_editor):
    """Reprend les anciennes cases « licence / master » dans les nouveaux niveaux de formation."""
    from django.utils.text import slugify
    Niveau = apps.get_model("filieres", "NiveauFormation")
    Filiere = apps.get_model("filieres", "Filiere")
    objets = {nom: Niveau.objects.get_or_create(nom=nom, defaults={"slug": slugify(nom), "ordre": o})[0] for nom, o in NIVEAUX}
    for f in Filiere.objects.all():
        if f.licence:
            f.niveaux.add(objets["Licence"])
        if f.master:
            f.niveaux.add(objets["Master"])


def restaurer_indicateurs(apps, schema_editor):
    Filiere = apps.get_model("filieres", "Filiere")
    for f in Filiere.objects.all():
        noms = set(f.niveaux.values_list("nom", flat=True))
        f.licence, f.master = "Licence" in noms, "Master" in noms
        f.save(update_fields=["licence", "master"])


